/// The value the header gives `name`.
///
/// # Panics
///
/// When `name` was never measured: add it to `cext layout`'s list.
pub fn measured(name: &str) -> u64 {
    CONSTS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, v)| *v)
        .unwrap_or_else(|| panic!("{name} was not measured; run `cargo xtask cext layout`"))
}
